relabel("y10maths", { number:[null, "Edexcel IGCSE 4MA1 · Numbers and the number system"], quadratics:[null, "Edexcel IGCSE 4MA1 · Equations, formulae and identities"], simultaneous:[null, "Edexcel IGCSE 4MA1 · Equations and inequalities"], graphs:[null, "Edexcel IGCSE 4MA1 · Graphs"], proportion:[null, "Edexcel IGCSE 4MA1 · Percentages and proportion"], trig:[null, "Edexcel IGCSE 4MA1 · Geometry and trigonometry"], mensuration:[null, "Edexcel IGCSE 4MA1 · Mensuration"], probability:[null, "Edexcel IGCSE 4MA1 · Probability and sets"], statistics:[null, "Edexcel IGCSE 4MA1 · Statistics"] });
U.y10maths.topics.push(topic("functions", "Functions and calculus", "Edexcel IGCSE 4MA1 · Functions and calculus (Higher)",
  ["f(x) is a rule: f(3) means 'put 3 into the rule'.","Composite functions: fg(x) means do g first, then f.","Inverse functions undo the original: swap x and y and rearrange to find f⁻¹(x).","Differentiation finds the gradient: if y = axⁿ, dy/dx = naxⁿ⁻¹. Constants differentiate to 0.","At a turning point (maximum or minimum), dy/dx = 0."],
  "Find f⁻¹(x) if f(x) = 3x − 6.\nWrite y = 3x − 6.\nSwap x and y: x = 3y − 6.\nRearrange: y = (x + 6) ÷ 3.\nSo f⁻¹(x) = (x + 6)/3.",
  [ex("How do you differentiate y = 4x³ − 5x + 2?", ["Bring the power down and multiply: 4 × 3 = 12, then reduce the power by 1: 12x².","−5x becomes −5 (x¹ → x⁰ = 1).","The constant 2 differentiates to 0.","dy/dx = 12x² − 5."], "dy/dx = 12x² − 5")],
  gen("y10maths/functions", "1112223333", 15101).concat([ m(2, "If f(x) = x² and g(x) = x + 1, which is gf(x)?", "x² + 1", ["(x + 1)²", "x³ + 1", "2x + 1"], "gf(x): f first (square), then g (add 1): x² + 1.") ]),
  [ m(1, "What does f(x) = 2x mean?", "A rule that doubles the input", ["f times x", "The function is 2", "x is 2"], "f(x) is notation for a rule applied to x."), m(2, "dy/dx of y = 7 is…", "0", ["7", "1", "7x"], "Constants have zero gradient."), m(3, "y = x² − 6x + 1 has a turning point at x = …", "3", ["−3", "6", "1"], "dy/dx = 2x − 6 = 0 → x = 3."), m(3, "Which value must be excluded from the domain of f(x) = 1/(x − 4)?", "x = 4", ["x = 0", "x = −4", "x = 1"], "Division by zero is undefined.") ]));

