relabel("y10biology", { cells:["Cells, transport and cell division", "Edexcel IGCSE 4BI1 · 2 Structures and functions: cell structure and movement of substances"], organisation:["Enzymes, nutrition and transport", "Edexcel IGCSE 4BI1 · 2 Structures and functions: biological molecules, nutrition and transport"], infection:["Disease, immunity and the immune response", "Edexcel IGCSE 4BI1 · 1 Variety (pathogens) and 2 Transport (immune response)"], bioenergetics:["Respiration and photosynthesis", "Edexcel IGCSE 4BI1 · 2 Structures and functions: respiration, gas exchange and plant nutrition"] });
U.y10biology.topics.unshift(topic("variety", "The nature and variety of living organisms", "Edexcel IGCSE 4BI1 · 1 The nature and variety of living organisms",
  ["All living organisms: need nutrition, respire, excrete, respond to their surroundings, move, control their internal conditions, reproduce, grow and develop.","Eukaryotes: plants (multicellular, chloroplasts, cellulose walls, store starch), animals (no walls, store glycogen, nervous coordination), fungi (hyphae/mycelium, chitin walls, saprotrophic nutrition), protoctists (mostly single-celled, e.g. Amoeba, Chlorella, Plasmodium).","Prokaryotes (bacteria): no nucleus, circular DNA and plasmids, e.g. Lactobacillus (yoghurt), Pneumococcus.","Viruses are not living cells: a protein coat around DNA or RNA; they reproduce only inside host cells (e.g. tobacco mosaic virus, influenza, HIV).","Pathogens include fungi, bacteria, protoctists and viruses."],
  "Is yeast a plant, animal, fungus or protoctist?\nIt has a cell wall made of chitin, so not an animal or plant.\nIt feeds by absorbing food (saprotrophic).\nSo yeast is a fungus (a single-celled one).",
  [ex("How do you classify an unknown organism?", ["Does it have a nucleus? No → bacterium (prokaryote).","Not a cell at all, just protein coat + genetic material → virus.","Has a nucleus: cell wall? chloroplasts? → plant.","Chitin wall, hyphae → fungus. No wall, nervous system → animal.","Mostly single-celled with a nucleus → protoctist."], "Work through nucleus → wall → nutrition.")],
  [ m(1, "Which group stores carbohydrate as glycogen?", "Animals", ["Plants", "Bacteria", "Viruses"], "Plants store starch; animals and fungi store glycogen."), m(1, "What are fungal threads called?", "Hyphae", ["Plasmids", "Flagella", "Villi"], "A network of hyphae forms a mycelium."), m(1, "Which is a protoctist that causes malaria?", "Plasmodium", ["Lactobacillus", "Mucor", "HIV"], "Plasmodium is a single-celled protoctist."), tf(1, "True or false: viruses can reproduce on their own.", false, "They only reproduce inside living host cells."), m(2, "What is saprotrophic nutrition?", "Secreting enzymes onto food and absorbing the digested products", ["Photosynthesis", "Eating other animals", "Living without food"], "Used by fungi such as Mucor."), m(2, "Which bacterium is used to make yoghurt?", "Lactobacillus bulgaricus", ["Pneumococcus", "Plasmodium", "Chlorella"], "It turns lactose into lactic acid."), m(3, "Why are viruses often described as non-living?", "They have no cell structure and can't carry out life processes outside a host", ["They are too small", "They have no genes", "They are plants"], "They lack cytoplasm, ribosomes and metabolism."), m(3, "Chlorella photosynthesises but is single-celled. Which group?", "Protoctist", ["Plant", "Fungus", "Bacterium"], "It's a single-celled organism with a nucleus and chloroplasts.") ],
  [ m(1, "What are the cell walls of plants made of?", "Cellulose", ["Chitin", "Protein", "Glycogen"], "Fungi use chitin."), m(2, "What is a plasmid?", "A small ring of extra DNA in bacteria", ["A virus coat", "A fungal thread", "A plant organelle"], "Often carries antibiotic resistance."), m(3, "Tobacco mosaic virus affects plants by…", "Damaging chloroplasts, causing a mosaic pattern and less photosynthesis", ["Killing roots", "Making leaves grow", "Adding nitrogen"], "Discoloured patches can't photosynthesise."), m(3, "Which characteristic of life describes getting rid of waste products of metabolism?", "Excretion", ["Egestion", "Respiration", "Nutrition"], "Egestion is removing undigested food.") ]));
U.y10biology.topics.push(
 topic("inheritance", "Reproduction and inheritance", "Edexcel IGCSE 4BI1 · 3 Reproduction and inheritance",
  ["Sexual reproduction: two gametes (haploid) fuse at fertilisation → diploid zygote; gives variation. Asexual: one parent, identical offspring (clones).","Genes are sections of DNA coding for proteins; alleles are different versions of a gene. Dominant alleles show when present; recessive alleles only show when homozygous.","Genotype (e.g. Bb) v phenotype (e.g. brown eyes). Homozygous (BB, bb) v heterozygous (Bb).","Mitosis: 2 identical diploid cells (growth, repair). Meiosis: 4 different haploid gametes.","Sex is determined by chromosomes: XX female, XY male. Mutations are random changes in DNA; natural selection can lead to evolution (e.g. antibiotic resistance)."],
  "Two heterozygous parents (Bb × Bb). Probability of a child with blue eyes (bb)?\nGametes: B or b from each parent.\nPunnett square gives BB, Bb, Bb, bb.\nbb is 1 of 4: probability 1/4 (25%). Ratio 3 brown : 1 blue.",
  [ex("How do you draw a Punnett square?", ["Write each parent's genotype.","Split into gametes along the top and side.","Fill each box with one allele from each gamete.","Count genotypes, then work out phenotypes and ratios."], "Gametes outside, offspring inside, then count.")],
  [ m(1, "What is an allele?", "A different version of a gene", ["A chromosome", "A gamete", "A cell"], "E.g. the allele for blue or brown eyes."), m(1, "How many chromosomes in a human gamete?", "23", ["46", "92", "12"], "Gametes are haploid."), m(1, "Which cell division makes gametes?", "Meiosis", ["Mitosis", "Binary fission", "Fertilisation"], "Meiosis halves the chromosome number."), m(2, "Bb is described as…", "Heterozygous", ["Homozygous dominant", "Homozygous recessive", "Haploid"], "Two different alleles."), n(2, "Bb × bb. What percentage of offspring are bb?", 50, "Offspring: Bb, Bb, bb, bb → 2 out of 4 = 50%."), m(2, "Which pair of sex chromosomes does a male have?", "XY", ["XX", "YY", "X only"], "The father's sperm decides the sex."), m(3, "Why does sexual reproduction produce variation?", "Meiosis shuffles alleles and fertilisation combines two parents' genes", ["Mitosis copies cells", "Clones form", "Mutations never occur"], "Variation helps species survive change."), m(3, "Why do bacteria become resistant to antibiotics?", "Random mutations give resistance; resistant bacteria survive and reproduce", ["They learn", "Antibiotics make them stronger", "Viruses help them"], "Natural selection in action.") ],
  [ tf(1, "True or false: asexual reproduction produces genetically identical offspring.", true, "Only one parent; mitosis copies the DNA."), m(2, "What is a phenotype?", "The physical characteristic shown", ["The alleles", "The DNA bases", "A chromosome"], "Genotype → phenotype."), m(3, "What is the probability a couple's child is a girl?", "50%", ["25%", "75%", "100%"], "XX × XY → XX, XX, XY, XY."), m(3, "What is codominance?", "Both alleles are expressed in the heterozygote", ["One allele hides another", "No alleles work", "A mutation"], "E.g. AB blood group.") ]),
 topic("ecology", "Ecology and the environment", "Edexcel IGCSE 4BI1 · 4 Ecology and the environment",
  ["Population, community, habitat and ecosystem. Use quadrats to estimate population size: mean per quadrat × (area ÷ quadrat area).","Food chains and webs: producers → primary → secondary → tertiary consumers. Pyramids of number, biomass and energy. Only about 10% of energy passes up each level.","Carbon cycle (photosynthesis, respiration, combustion, decomposition) and nitrogen cycle (nitrogen fixation, nitrification, denitrification, decomposition).","Human effects: air pollution (sulfur dioxide → acid rain, carbon monoxide), greenhouse gases (CO₂, methane, water vapour, nitrous oxide, CFCs) and global warming.","Water pollution: fertiliser causes eutrophication (algal bloom → plants die → bacteria use up oxygen → fish die). Deforestation reduces biodiversity and increases CO₂."],
  "Estimate daisies on a 50 m × 20 m field. Ten 1 m² quadrats found a mean of 3 daisies.\nField area = 1000 m².\nEstimate = 3 × 1000 = 3000 daisies.",
  [ex("How does eutrophication happen?", ["Fertiliser runs off into a lake.","Nitrates cause algae to grow fast (algal bloom).","Algae block light; plants below die.","Decomposing bacteria multiply and use up oxygen.","Fish suffocate and die."], "Nutrients → algae → no light → decomposers use oxygen → fish die.")],
  [ m(1, "What is an ecosystem?", "A community of organisms and their physical environment", ["One species", "A food chain", "A habitat only"], "Biotic + abiotic."), n(1, "Mean of 4 plants per 1 m² quadrat in a 200 m² field. Estimate the population.", 800, "4 × 200 = 800."), m(1, "Which gas causes acid rain?", "Sulfur dioxide", ["Oxygen", "Nitrogen", "Argon"], "From burning fossil fuels containing sulfur."), m(2, "Why is energy lost between trophic levels?", "Respiration, movement, heat and waste (faeces, urine)", ["It isn't", "Plants take it back", "Sunlight stops"], "Only about 10% passes on."), m(2, "Which bacteria convert nitrogen gas into nitrogen compounds?", "Nitrogen-fixing bacteria", ["Denitrifying bacteria", "Decomposers only", "Pathogens"], "Found in soil and root nodules of legumes."), m(2, "Why is methane a concern?", "It is a powerful greenhouse gas from cattle and rice fields", ["It makes ozone", "It cools the Earth", "It is harmless"], "It traps more heat than CO₂ per molecule."), m(3, "Why do fish die in eutrophication?", "Bacteria decomposing dead plants use up dissolved oxygen", ["Algae eat them", "Too much light", "The water gets salty"], "Oxygen falls, so aerobic organisms die."), m(3, "A pyramid of numbers can be inverted. Why?", "One large producer (e.g. a tree) supports many consumers", ["Energy increases", "Mistakes", "Animals photosynthesise"], "Pyramids of biomass avoid this.") ],
  [ m(1, "What is a habitat?", "The place where an organism lives", ["A food chain", "A population", "A community"], ""), m(2, "What does carbon monoxide do?", "Binds to haemoglobin, reducing oxygen carried", ["Causes acid rain", "Feeds plants", "Kills bacteria"], "It's colourless and odourless."), m(3, "Which process returns nitrogen gas to the air?", "Denitrification", ["Nitrification", "Fixation", "Photosynthesis"], "Done by denitrifying bacteria in waterlogged soil."), m(3, "How does deforestation increase CO₂?", "Less photosynthesis, and burning or decomposing trees releases CO₂", ["Trees make CO₂", "Soil absorbs CO₂", "It doesn't"], "") ]),
 topic("resources", "Use of biological resources", "Edexcel IGCSE 4BI1 · 5 Use of biological resources",
  ["Glasshouses and polythene tunnels increase crop yield by controlling temperature, CO₂ and light. Fertilisers add minerals; pest control (pesticides or biological control) reduces losses.","Microorganisms: yeast in bread-making and brewing (anaerobic respiration makes CO₂ and ethanol); Lactobacillus in yoghurt.","Industrial fermenters keep conditions ideal: aseptic precautions, nutrients, optimum temperature and pH, oxygen and stirring.","Selective breeding chooses parents with desired features (e.g. high-yield wheat, dairy cows). Fish farming controls water, feeding and disease.","Genetic modification: restriction enzymes cut DNA, ligase joins it into a plasmid vector, e.g. human insulin made by bacteria. Cloning: plant micropropagation and Dolly the sheep."],
  "How do bacteria make human insulin?\nCut the insulin gene out of human DNA with restriction enzymes.\nCut a plasmid with the same enzyme; join with ligase.\nPut the recombinant plasmid into bacteria.\nGrow the bacteria in a fermenter; they make insulin.",
  [ex("How do you explain why a glasshouse increases yield?", ["Name the limiting factor (temperature, CO₂, light).","Explain how the glasshouse raises it (traps heat, paraffin heater adds CO₂, artificial lighting).","Link to faster photosynthesis → more growth.","Mention that the extra cost must be covered by the extra yield."], "Limiting factor → raised → more photosynthesis → bigger yield.")],
  [ m(1, "Why does bread dough rise?", "Yeast produces carbon dioxide", ["Flour expands", "Oxygen is added", "Water boils"], "Anaerobic respiration of yeast."), m(1, "What do pesticides do?", "Kill pests that damage crops", ["Add nutrients", "Make rain", "Increase CO₂"], ""), m(1, "Which bacterium makes yoghurt?", "Lactobacillus", ["Plasmodium", "Yeast", "Salmonella"], ""), m(2, "What is biological control?", "Using a natural predator or parasite to control a pest", ["Spraying chemicals", "Adding fertiliser", "Ploughing"], "E.g. ladybirds eat aphids."), m(2, "Why are fermenters kept aseptic?", "To stop contamination by unwanted microorganisms", ["To add oxygen", "To keep them cold", "To make them faster"], "Steam sterilisation is used."), m(2, "What does a restriction enzyme do?", "Cuts DNA at specific sequences", ["Joins DNA", "Copies DNA", "Kills bacteria"], "Ligase joins DNA."), m(3, "Why are fermenters stirred?", "To spread nutrients, oxygen and heat evenly", ["To kill microbes", "To cool them only", "For decoration"], ""), m(3, "What is a disadvantage of selective breeding?", "Reduced genetic variation, so less resistance to new diseases", ["It is quick", "It increases variety", "It uses GM"], "Inbreeding can cause health problems.") ],
  [ m(2, "What is a vector in genetic modification?", "A plasmid or virus that carries a gene into a cell", ["An insect", "A protein", "A fertiliser"], ""), m(3, "What is micropropagation?", "Growing many identical plants from small pieces of tissue", ["Selective breeding", "Fertilisation", "Grafting only"], "Also called tissue culture."), m(3, "Why does fish farming use small nets or tanks?", "To control conditions and reduce energy used in swimming", ["To let fish escape", "To increase predators", "To lower food"], "Disease can spread easily, though."), m(3, "Why add paraffin heaters to glasshouses?", "They raise temperature and CO₂ concentration", ["They add light", "They add water", "They kill weeds"], "") ]));

