U.y10chemistry.topics.push(
 topic("rates", "Rates of reaction and equilibria", "Edexcel IGCSE 4CH1 · 3 Physical chemistry",
  ["Rate increases with higher temperature, concentration (or gas pressure), surface area (smaller pieces) and a catalyst.","Collision theory: particles must collide with at least the activation energy. More frequent or more energetic collisions = faster rate.","Catalysts provide an alternative pathway with lower activation energy and are not used up.","Measure rate by gas volume over time, mass lost, or time for a precipitate to hide a cross.","Reversible reactions (⇌) can reach dynamic equilibrium in a closed system: forward and backward rates are equal (e.g. hydrated copper(II) sulfate ⇌ anhydrous + water)."],
  "Why does powdered marble react faster with acid than lumps?\nPowder has a larger surface area.\nMore particles are exposed to acid.\nMore collisions per second → faster reaction.",
  [ex("How do you find the rate from a graph of gas volume v time?", ["The steeper the line, the faster the rate.","Mean rate = total volume ÷ time taken.","For rate at a point, draw a tangent and find its gradient.","When the line goes flat, the reaction has stopped (a reactant is used up)."], "Rate = gradient of the curve.")],
  [ m(1, "Which change speeds up a reaction?", "Increasing the temperature", ["Using bigger lumps", "Diluting the acid", "Cooling it"], "Particles move faster and collide more energetically."), m(1, "What does a catalyst do?", "Speeds up a reaction without being used up", ["Slows it down", "Becomes a product", "Increases activation energy"], ""), n(1, "40 cm³ of gas is made in 20 s. Mean rate in cm³/s?", 2, "40 ÷ 20 = 2 cm³/s."), m(2, "Why does higher concentration increase rate?", "More particles in the same volume, so more frequent collisions", ["Particles move faster", "Activation energy falls", "Bigger particles"], ""), m(2, "What does ⇌ mean?", "The reaction is reversible", ["It goes faster", "It's exothermic", "It needs a catalyst"], ""), m(2, "At dynamic equilibrium…", "Forward and backward reactions happen at the same rate", ["Reactions stop", "Only products remain", "The system is open"], "Concentrations stay constant."), m(3, "Why does raising temperature by 10 °C often double the rate?", "Many more particles have energy above the activation energy", ["Particles get bigger", "The catalyst works", "Concentration doubles"], "Both more collisions and more successful ones."), m(3, "Blue hydrated copper(II) sulfate is heated. What happens?", "It turns white as water is driven off; adding water turns it blue again", ["It turns red forever", "Nothing", "It melts into blue liquid"], "A reversible reaction used as a test for water.") ],
  [ m(2, "Why might a reaction graph level off?", "One reactant has been used up", ["The catalyst ran out", "It sped up", "Pressure fell"], ""), m(3, "How does a catalyst affect the energy profile?", "It lowers the activation energy", ["It raises the products", "It changes ΔH", "No change"], ""), m(3, "Increasing gas pressure speeds up a gas reaction because…", "Particles are closer together, so they collide more often", ["They get hotter", "They react less", "The catalyst works"], ""), tf(2, "True or false: a catalyst changes the amount of product formed.", false, "It only changes how fast it forms.") ]),
 topic("organic", "Organic chemistry: crude oil, alkanes and alkenes", "Edexcel IGCSE 4CH1 · 4 Organic chemistry",
  ["Hydrocarbons contain only hydrogen and carbon. Crude oil is separated by fractional distillation into fractions (refinery gases, gasoline, kerosene, diesel, fuel oil, bitumen).","Larger molecules: higher boiling point, more viscous, harder to ignite. Combustion: complete → CO₂ + H₂O; incomplete → CO (toxic) and soot.","Alkanes CₙH₂ₙ₊₂ (saturated, single C–C bonds, e.g. methane, ethane). Alkenes CₙH₂ₙ (unsaturated, C=C double bond, e.g. ethene).","Test for alkenes: bromine water turns from orange to colourless.","Cracking breaks long alkanes into shorter alkanes and alkenes (heat + catalyst), meeting demand for petrol and making ethene for plastics. Addition polymers (e.g. poly(ethene)) form from alkenes."],
  "Write the formula of the alkane with 5 carbons.\nAlkanes: CₙH₂ₙ₊₂.\nn = 5 → H = 2 × 5 + 2 = 12.\nC₅H₁₂ (pentane).",
  [ex("How do you tell an alkane from an alkene?", ["Add bromine water to each.","Alkene: orange → colourless (the C=C bond reacts).","Alkane: stays orange.","Explain: alkenes are unsaturated."], "Bromine water decolourises with alkenes.")],
  [ m(1, "What does a hydrocarbon contain?", "Only hydrogen and carbon", ["Hydrogen, carbon and oxygen", "Only carbon", "Water"], ""), m(1, "What is the general formula of alkanes?", "CₙH₂ₙ₊₂", ["CₙH₂ₙ", "CₙH₂ₙ₋₂", "CₙHₙ"], ""), m(1, "Which fraction is used for road surfaces?", "Bitumen", ["Gasoline", "Kerosene", "Refinery gases"], "It's the most viscous fraction."), n(2, "How many hydrogen atoms are in an alkane with 8 carbon atoms?", 18, "2 × 8 + 2 = 18 (octane, C₈H₁₈)."), m(2, "What does bromine water do with an alkene?", "Turns from orange to colourless", ["Turns blue", "Stays orange", "Turns red"], ""), m(2, "Why is incomplete combustion dangerous?", "It produces toxic carbon monoxide", ["It makes oxygen", "It cools rooms", "It makes CO₂ only"], ""), m(3, "Why is cracking needed?", "To turn long, less useful alkanes into shorter, in-demand fuels and alkenes", ["To make crude oil", "To make water", "To remove sulfur"], "Supply of long chains exceeds demand."), m(3, "Which is the monomer of poly(ethene)?", "Ethene", ["Ethane", "Methane", "Propane"], "The C=C bond opens to join monomers.") ],
  [ m(2, "Why do longer hydrocarbons have higher boiling points?", "Stronger intermolecular forces between larger molecules", ["More double bonds", "They are ionic", "They are lighter"], ""), m(3, "What are the conditions for catalytic cracking?", "About 600–700 °C with a silica or alumina catalyst", ["Room temperature", "Freezing", "Electrolysis"], ""), m(3, "Why are addition polymers hard to dispose of?", "They are non-biodegradable, and burning releases toxic gases", ["They dissolve", "They rot quickly", "They are metals"], ""), tf(2, "True or false: alkanes are saturated hydrocarbons.", true, "Only single C–C bonds.") ]));

