U.y10history.topics.push(
 topic("usa", "A divided union: civil rights in the USA, 1945–74", "Edexcel IGCSE 4HI1 · Paper 1 depth study",
  ["Post-war America: the Red Scare and McCarthyism (late 1940s–1954).","Segregation in the South ('Jim Crow' laws). Brown v Board of Education (1954) ruled school segregation unconstitutional; Little Rock (1957).","Montgomery Bus Boycott (1955–56) after Rosa Parks' arrest; Martin Luther King's non-violent protest; sit-ins (1960), Freedom Rides (1961), Birmingham (1963), March on Washington (1963).","Civil Rights Act (1964) and Voting Rights Act (1965). Malcolm X, Black Power and the Black Panthers.","Other protest movements: students and opposition to the Vietnam War, women's movement (NOW, Roe v Wade 1973); Watergate (1972–74) and Nixon's resignation."],
  "Why was the Montgomery Bus Boycott successful?\nAbout 50 000 Black residents refused to ride the buses for 381 days, hitting the bus company's income.\nIt was well organised (car pools) and led by Martin Luther King.\nThe Supreme Court ruled bus segregation unconstitutional (1956).",
  [ex("How do you answer 'Explain why…' (12 marks)?", ["Use the given stimulus points AND your own knowledge.","Write 3 developed paragraphs, each explaining one reason.","Link each reason back to the question.","Conclude by saying which reason mattered most."], "3 explained reasons + judgement.")],
  [ n(1, "In which year did the Brown v Board of Education ruling happen?", 1954, "It overturned 'separate but equal' in schools."), m(1, "Who was arrested for refusing to give up her bus seat?", "Rosa Parks", ["Ruby Bridges", "Coretta Scott King", "Elizabeth Eckford"], ""), m(1, "What did the Civil Rights Act (1964) do?", "Banned segregation in public places and discrimination in employment", ["Gave women the vote", "Ended the Vietnam War", "Started the Red Scare"], ""), m(2, "What happened at Little Rock in 1957?", "Nine Black students needed federal troops to attend a white high school", ["A bus boycott", "A march", "A riot in Detroit"], ""), m(2, "What were the Freedom Rides (1961)?", "Mixed-race groups rode buses to challenge segregated bus terminals", ["Car races", "A strike", "A court case"], ""), m(2, "Who was a leading figure in the Black Power movement?", "Malcolm X (and later Stokely Carmichael)", ["Martin Luther King", "Rosa Parks", "Lyndon Johnson"], ""), m(3, "Why was the Voting Rights Act (1965) important?", "It banned literacy tests and other barriers, greatly increasing Black voter registration in the South", ["It ended segregation", "It gave women equal pay", "It ended McCarthyism"], "It followed the Selma marches."), m(3, "Why did Nixon resign in 1974?", "The Watergate scandal: cover-up of a break-in at Democratic headquarters", ["He lost an election", "Vietnam", "Ill health"], "") ],
  [ m(1, "Who gave the 'I have a dream' speech?", "Martin Luther King", ["Malcolm X", "JFK", "Rosa Parks"], "At the March on Washington, 1963."), m(2, "What was McCarthyism?", "Accusing people of communist sympathies, often without evidence", ["A civil rights group", "A law", "A protest"], ""), m(3, "Why did some young Black Americans turn to Black Power?", "Frustration at slow progress, poverty and continued violence", ["King asked them to", "They supported segregation", "Laws required it"], ""), m(3, "What did Roe v Wade (1973) decide?", "Women had a constitutional right to abortion", ["Equal pay", "School desegregation", "Voting rights"], "") ]),
 topic("ww1", "The origins and course of the First World War, 1905–18", "Edexcel IGCSE 4HI1 · Paper 2 historical investigation",
  ["Long-term causes: alliances (Triple Alliance and Triple Entente), naval race (Dreadnoughts), Moroccan Crises (1905, 1911), Balkan tensions.","Short-term trigger: assassination of Archduke Franz Ferdinand in Sarajevo (28 June 1914).","Schlieffen Plan failed: Belgian resistance, the BEF, the Russian mobilisation and the Battle of the Marne. Stalemate and trench warfare followed.","Key battles: Verdun and the Somme (1916), Gallipoli (1915), Jutland (1916), Passchendaele (1917).","The war ended in 1918: the USA joined (1917), the German Spring Offensive failed, the Allied Hundred Days, and the armistice on 11 November 1918."],
  "Why did the Schlieffen Plan fail?\nBelgium resisted, delaying Germany.\nBritain's BEF fought at Mons.\nRussia mobilised faster than expected, so troops were moved east.\nThe Battle of the Marne stopped the advance on Paris.",
  [ex("How do you analyse an interpretation (Paper 2)?", ["Say what the interpretation argues.","Use the sources and your knowledge to support it.","Use evidence that challenges it.","Judge how far you agree, with a reason."], "Agree, challenge, then judge.")],
  [ m(1, "Who was assassinated on 28 June 1914?", "Archduke Franz Ferdinand", ["Kaiser Wilhelm", "Tsar Nicholas", "King George V"], ""), m(1, "Which countries formed the Triple Entente?", "Britain, France and Russia", ["Germany, Austria-Hungary and Italy", "Britain, USA and Japan", "France, Italy and Spain"], ""), n(1, "In which year did the war end?", 1918, "Armistice on 11 November 1918."), m(2, "What was the Schlieffen Plan?", "Germany's plan to defeat France quickly through Belgium, then turn on Russia", ["A peace treaty", "A naval plan", "A British plan"], ""), m(2, "What was a Dreadnought?", "A powerful new type of battleship", ["A tank", "An aircraft", "A trench"], "The naval race increased Anglo-German rivalry."), m(2, "Which battle in 1916 saw about 57 000 British casualties on its first day?", "The Somme", ["Verdun", "Jutland", "Marne"], ""), m(3, "Why is Jutland (1916) debated?", "Britain lost more ships, but Germany's fleet stayed in port afterwards", ["Germany won the war there", "It ended the war", "No ships fought"], ""), m(3, "Why did the USA join the war in 1917?", "Unrestricted submarine warfare and the Zimmermann Telegram", ["Germany invaded the USA", "To help Russia only", "The Schlieffen Plan"], "") ],
  [ m(1, "What was 'no man's land'?", "The ground between opposing trenches", ["A country", "A trench", "A hospital"], ""), m(2, "What happened at Gallipoli (1915)?", "A failed Allied attempt to knock Turkey out of the war", ["A German victory in France", "A naval victory", "The armistice"], ""), m(3, "Why was the Battle of the Marne (1914) a turning point?", "It stopped the German advance on Paris and led to trench stalemate", ["It ended the war", "Russia surrendered", "The USA joined"], ""), m(3, "Which new weapon was first used at the Somme?", "The tank", ["Poison gas", "The machine gun", "The submarine"], "") ]),
 topic("medicine", "Changes in medicine, c1848–c1948", "Edexcel IGCSE 4HI1 · Paper 2 breadth study in change",
  ["Causes of disease: miasma replaced by germ theory (Pasteur 1861) and Koch's work identifying specific bacteria.","Surgery: anaesthetics (chloroform, Simpson 1847), antiseptics (Lister 1867), then aseptic surgery; blood transfusions and blood groups (Landsteiner 1901).","Public health: cholera and Snow (1854), Public Health Acts (1848, 1875), Liberal reforms (1906–11), the NHS (1948).","Treatment: vaccines (Pasteur's anthrax and rabies), magic bullets (Salvarsan 606, 1909; Prontosil), penicillin (Fleming 1928; Florey and Chain 1940s).","War and medicine: WWI advances in X-rays, plastic surgery and blood storage; WWII mass production of penicillin."],
  "How did germ theory change surgery?\nLister read Pasteur's work and used carbolic acid to kill germs.\nInfection rates fell sharply.\nThis led to aseptic surgery: sterilised instruments, gowns and gloves.",
  [ex("How do you answer 'How far…' about change?", ["Explain evidence of change.","Explain evidence of continuity or limits.","Compare the extent of each.","Reach a judgement: 'to a large extent because…'."], "Change v continuity, then judge.")],
  [ m(1, "Who published germ theory in 1861?", "Louis Pasteur", ["Joseph Lister", "Robert Koch", "Edward Jenner"], ""), m(1, "Who introduced carbolic acid antiseptic?", "Joseph Lister", ["James Simpson", "Alexander Fleming", "John Snow"], ""), n(1, "In which year was the NHS founded?", 1948, ""), m(2, "What was the first 'magic bullet' (1909)?", "Salvarsan 606, for syphilis", ["Penicillin", "Aspirin", "Prontosil"], "Developed by Ehrlich and Hata."), m(2, "What did Landsteiner discover in 1901?", "Blood groups", ["X-rays", "Penicillin", "Germs"], "This made transfusions safer."), m(2, "How did WWI help surgery?", "Advances in X-rays, blood storage and plastic surgery", ["It stopped all research", "It discovered germs", "It created the NHS"], ""), m(3, "Why was penicillin not mass-produced until the 1940s?", "It needed purifying and funding; WWII created the demand and US investment", ["Fleming hid it", "It didn't work", "It was banned"], ""), m(3, "Why were the Liberal reforms (1906–11) significant?", "Government took responsibility for welfare: free school meals, pensions, National Insurance", ["They created the NHS", "They ended cholera", "They discovered germs"], "") ],
  [ m(1, "What did miasma theory blame for disease?", "Bad air", ["Germs", "God only", "Water"], ""), m(2, "What did Koch do?", "Identified specific bacteria causing specific diseases (e.g. TB, cholera)", ["Invented vaccines", "Discovered penicillin", "Built sewers"], ""), m(3, "Why did the Public Health Act of 1875 matter more than 1848?", "It was compulsory: councils had to provide clean water and sewers", ["It was voluntary", "It created the NHS", "It banned miasma"], ""), m(3, "Who led the creation of the NHS?", "Aneurin Bevan", ["Winston Churchill", "Lloyd George", "Florence Nightingale"], "") ]));

